def cycleEntry(succ):
    # nodes are indices into succ; -1 plays the role of null
    slow = fast = 0
    while True:
        if fast == -1 or succ[fast] == -1:
            return -1
        slow = succ[slow]
        fast = succ[succ[fast]]
        if slow == fast:
            break
    slow = 0
    while slow != fast:
        slow = succ[slow]
        fast = succ[fast]
    return slow
